Artisan::command('ghar:demo',function(){if(!app()->environment('local','testing')){$this->error('Demo data is forbidden outside local/testing.');return 1;}$user=User::firstOrCreate(['email'=>'demo@ghar.test'],['name'=>'Demo Homeowner','password'=>'LocalDemo!2026']);if(!Project::where('user_id',$user->id)->exists()){$p=new Project(['name'=>'Budhanilkantha Family Home','location'=>'Budhanilkantha, Kathmandu','budget_paisa'=>850000000]);$p->user_id=$user->id;$p->save();$now=now();foreach([['Cement','Bagmati Building Supply','bag',120000,95025],['Rebar','Valley Steel','kg',1250000,9850],['Bricks','Local Brick Works','piece',8000000,1850]] as [$name,$supplier,$unit,$quantity,$rate]){\Illuminate\Support\Facades\DB::table('materials')->insert(['project_id'=>$p->id,'name'=>$name,'supplier'=>$supplier,'unit'=>$unit,'quantity_milli'=>$quantity,'rate_paisa'=>$rate,'total_paisa'=>\App\Support\Decimal::total($quantity,$rate),'recorded_on'=>$now->toDateString(),'created_at'=>$now,'updated_at'=>$now]);}\Illuminate\Support\Facades\DB::table('daily_logs')->insert(['project_id'=>$p->id,'client_uuid'=>(string)\Illuminate\Support\Str::uuid(),'recorded_on'=>$now->toDateString(),'notes'=>'DEMO: Foundation reinforcement review recorded. Confirm the next concrete delivery with the site engineer.','created_at'=>$now,'updated_at'=>$now]);}$this->info('Local demo initialized. See README for development-only credentials.');});
